# DK USB.  Ustrup - Skærbæk Amtsbane
with detail = 2 {
    let us = path("d2.dk.usb");

    with railway = :first :g1000 :pax :removed {
        with link = "line.dk.USB" {
            track(
                    us[:ust.ys, :oje.xn - 0.5md]
                ..  us[:oje.yn, :oje.yn + 0.1ld] << 0.5md >> 0.5lt
            );
        }

        # point.dk.Over-Jerstal-Amtsb

        with link = "line.dk.USB" {
            track(
                    us[:oje.ys - 0.1dl, :oje.ys] >> 0.5md << 0.5lt
                ..  us[:oje.xs + 0.5md, :oje.xs + 6.01km]
            );
            line_label(:left:n, us[:oje.xs + 6km] << 0.5lt,
                (0.2dt, 0dt), "USB"
            );
            track(us[:oje.xs + 5.99km, :arn.yv - 6.59km]);
            line_label(:right:sw, us[:arn.yv - 6.6km] >> 0.5lt, "USB");
            track(us[:arn.yv - 6.61km, :arn.yv]);
        }

        with link = "point.dk.Arnum", railway = :station {
            track(us[:arn.yv, :arn]);
            statdot(us[:arn]);
            slabel(:ne, us[:arn] + (0dt, 0.7dt), "Arnum");
        }

        with link = "line.dk.USB" {
            track(us[:arn, :arn + 14.01km]);
            line_label(:left:w, us[:arn + 14km] << 0.5lt, "USB");
            track(us[:arn + 13.99km, :ska.yu]);
        }
    }
}

